-- Shorter checkbox notices requested during review; preserve the immutable initial version.
insert into public.privacy_policy_versions(version,content)
values ('2026-10-26.v2',$policy${"version": "2026-10-26.v2", "publishedAt": "26 de octubre de 2026", "contact": "comercial@camaraica.org.pe", "notices": {"individual": "He leído la Política de privacidad y autorizo el uso de mis datos para gestionar mi inscripción y certificados.", "campus": "He leído la Política de privacidad y autorizo el uso de mis datos para mi cuenta y formación en el Campus.", "group": "Confirmo que todos los asistentes conocen la Política de privacidad y autorizan el uso de sus datos para su inscripción y certificados.", "marketing": "Quiero recibir información de próximos eventos, capacitaciones y cursos por correo y WhatsApp.", "groupMarketing": "Cuento con la autorización de todos los asistentes para recibir información de próximas actividades por correo y WhatsApp."}, "sections": [{"title": "Quién trata tus datos", "paragraphs": ["La Cámara de Comercio de Ica es responsable del tratamiento de los datos recogidos por este portal de eventos, capacitaciones y Campus Virtual. Nuestro domicilio institucional es Urb. Sr. de Luren, C. Pedro Olaechea 285, Ica, Perú. Para consultas y solicitudes de privacidad escribe a comercial@camaraica.org.pe."]}, {"title": "Qué datos recogemos", "paragraphs": ["Según el servicio, solicitamos nombres, DNI o CE, correo y celular; empresa u organización, RUC, cargo y provincia; o institución educativa y carrera. También registramos inscripciones, asistencia, progreso académico, evaluaciones y certificados. Para actividades pagadas recogemos los datos necesarios para el comprobante y la gestión del pago; no pedimos datos de tarjetas bancarias en los formularios de inscripción.", "Los campos obligatorios están identificados. Los opcionales pueden quedar vacíos. Si no proporcionas los datos necesarios o no autorizas el tratamiento requerido para el registro, no podremos completar esa inscripción o cuenta. No aceptar publicidad no limita tu participación."]}, {"title": "Para qué los utilizamos", "paragraphs": ["Usamos tus datos para gestionar tu inscripción o cuenta, cupos y accesos, comunicaciones sobre la actividad, asistencia, pagos y comprobantes cuando correspondan, formación, soporte y certificados. No utilizamos la aceptación de inscripción como autorización para publicidad.", "Solo si marcas la casilla opcional utilizaremos tu correo y celular para informarte de próximos eventos, capacitaciones y cursos por correo y WhatsApp. Puedes retirar esa autorización sin afectar tus inscripciones ni certificados. En registros grupales, quien registra declara que informó y obtuvo la autorización de todos los asistentes para las finalidades seleccionadas."]}, {"title": "Quién puede acceder y proveedores tecnológicos", "paragraphs": ["El personal autorizado de la Cámara accede a los datos necesarios para sus funciones. Utilizamos Supabase para base de datos, autenticación y archivos; Vercel para alojamiento; y herramientas de automatización y correo para comunicaciones operativas. El Campus puede usar Vimeo para reproducir clases. Al usar WhatsApp o acceder a enlaces externos también se aplican las condiciones de esos servicios.", "Estos proveedores pueden tratar datos fuera del Perú para prestar sus servicios. El portal no publica documentos de identidad ni datos de contacto de participantes en los catálogos públicos. Las verificaciones de certificados muestran únicamente la información necesaria para comprobarlos. No ofrecemos tus datos como una base de contactos de libre acceso."]}, {"title": "Durante cuánto tiempo los conservamos", "paragraphs": ["Conservamos los datos mientras sean necesarios para gestionar los servicios solicitados y cumplir obligaciones legales aplicables. Los registros académicos, certificados y evidencias de autorización pueden mantenerse cuando sean necesarios para acreditar la formación, verificar documentos o atender responsabilidades. Una solicitud de cancelación se evaluará considerando estas obligaciones; retirar la publicidad no elimina el historial académico."]}, {"title": "Tus derechos y cómo dejar de recibir publicidad", "paragraphs": ["Puedes solicitar acceso, rectificación, cancelación u oposición al tratamiento de tus datos y retirar tu consentimiento escribiendo a comercial@camaraica.org.pe, indicando tu solicitud y los datos necesarios para identificar el registro. Verificaremos tu identidad de forma proporcional antes de entregar o modificar información. No envíes contraseñas.", "Para dejar de recibir publicidad, escribe al mismo correo indicando “Baja de publicidad”. La Cámara registrará la baja y dejará de incluirte en sus listas promocionales. Esto no impide las comunicaciones necesarias sobre actividades en las que ya participas. Si consideras que tus derechos no han sido atendidos, puedes acudir a la Autoridad Nacional de Protección de Datos Personales."]}, {"title": "Cookies y estadísticas", "paragraphs": ["El portal utiliza cookies necesarias para autenticación y funcionamiento. Cuando Google Analytics está configurado, también registra estadísticas de navegación mediante cookies e identificadores del navegador. No enviamos a Analytics nombres, documentos, RUC, correos ni teléfonos de los formularios. Puedes administrar las cookies desde tu navegador; bloquear las necesarias puede afectar el acceso al Campus.", "Esta versión del portal no muestra un aviso de aceptación de cookies de analítica. La aceptación del formulario se refiere a las finalidades descritas en sus casillas y no se registra como consentimiento de Analytics."]}, {"title": "Cambios de esta política", "paragraphs": ["Identificamos cada versión de esta política y conservamos el texto vinculado a las aceptaciones registradas. Si cambiamos las finalidades que requieren autorización, solicitaremos la aceptación correspondiente. Esta política se interpreta conforme a la Ley N.º 29733 y su reglamento vigente."]}]}$policy$::jsonb);
create or replace function public.current_privacy_version() returns text
language sql immutable set search_path = '' as $$ select '2026-10-26.v2'::text $$;
